struct_with_invariants!{

    pub struct RwLock<V, Pred: RwLockPredicate<V>> {
        exc: AtomicBool<_, RwLockToks::flag_exc<Pred, V, InternalPred<V, Pred>>, _>,
        rc: AtomicUsize<_, RwLockToks::flag_rc<Pred, V, InternalPred<V, Pred>>, _>,

